package mz.bam.seeky.android;
import android.app.*;import android.content.*;import android.database.*;import android.graphics.*;import android.graphics.pdf.PdfDocument;import android.net.Uri;import android.os.Bundle;import android.widget.*;import org.json.*;import java.io.*;import java.util.*;
/** Selection first, then a printable PDF. Long note bodies are loaded one at a time. */
final class RevisionNotebook {
 static final int REQUEST=81;final Activity a;final String uri,title;final long material,subject;File pending;
 static final class Choice{String kind,title,source,uri="",digest="",signature="";long id;int part,index;Choice(String kind,long id,String title,String source){this.kind=kind;this.id=id;this.title=title;this.source=source;}}
 RevisionNotebook(Activity a,String uri,long material,long subject,String title){this.a=a;this.uri=uri;this.material=material;this.subject=subject;this.title=title==null?"Estudos":title;}
 void choose(){new RevisionPicker(this).show();}
 interface Visitor{void item(Choice item)throws Exception;}
 static final class Page{final List<Choice> rows;final int total;Page(List<Choice> rows,int total){this.rows=rows;this.total=total;}}
 String key(Choice item){return item.uri+"|"+item.id+"|"+item.part+"|"+item.index+"|"+item.digest;}
 List<Choice> choices()throws Exception{List<Choice> out=new ArrayList<>();visit("",out::add);return out;}
 Page page(String query,int offset,int limit)throws Exception{List<Choice> out=new ArrayList<>();int[] at={0};visit(query,item->{if(at[0]>=offset&&out.size()<limit)out.add(item);at[0]++;});return new Page(out,at[0]);}
 void visit(String query,Visitor visitor)throws Exception{String q=query.trim().toLowerCase(Locale.ROOT);try(StudyStore db=new StudyStore(a)){String where=material>0?"material IN (SELECT same.id FROM materials same WHERE same.hash=(SELECT hash FROM materials WHERE id=?))":subject>0?"subject=?":null;for(String table:new String[]{"notes","cards","questions"}){String heading=table.equals("notes")?"title":table.equals("cards")?"front":"prompt";String selection=(where==null?"":where+" AND ")+heading+" LIKE ? ESCAPE '\\'";List<String> args=new ArrayList<>();if(where!=null)args.add(""+(material>0?material:subject));args.add(StudySchedule.like(query));try(Cursor c=db.getReadableDatabase().query(table,new String[]{"id",heading,"material",table.equals("questions")?"0 AS segment":"segment","(SELECT title FROM materials WHERE id="+table+".material) AS origin"},selection,args.toArray(new String[0]),null,null,"updated DESC,id DESC")){while(c.moveToNext()){String label=table.equals("notes")?"Nota":table.equals("cards")?"Cartão":"Pergunta";String origin=c.isNull(4)?title:c.getString(4)+(table.equals("questions")?"":" · "+AppLanguage.text(a,"Parte")+" "+(c.getInt(3)+1));Choice item=new Choice(label,c.getLong(0),c.getString(1),origin);item.uri=table;item.part=c.getInt(3);visitor.item(item);}}}}
 if(!uri.isEmpty())try(ReaderStore db=new ReaderStore(a);Cursor c=db.getReadableDatabase().query("draft",new String[]{"segment","digest","marks"},"uri=?",new String[]{uri},null,null,"segment,digest")){while(c.moveToNext()){JSONArray marks=new JSONArray(c.getString(2));for(int n=0;n<marks.length();n++){JSONObject mark=marks.getJSONObject(n);String kind=mark.optString("k"),note=mark.optString("n");String label=kind.equals("note")?"Nota de leitura":kind.equals("underline")?"Sublinhado":"Destaque";String caption=note.isEmpty()?title:note;if(!q.isEmpty()&&!(caption+" "+label+" "+(c.getInt(0)+1)).toLowerCase(Locale.ROOT).contains(q))continue;Choice item=new Choice(label,0,caption,title+" · "+AppLanguage.text(a,"Parte")+" "+(c.getInt(0)+1));item.uri=uri;item.digest=c.getString(1);item.part=c.getInt(0);item.index=n;item.signature=ReaderStore.digest(mark.toString());visitor.item(item);}}}}
 String body(Choice item)throws Exception{if(item.id>0)try(StudyStore db=new StudyStore(a)){StudyStore.Row row=db.get(item.uri,item.id);if(row==null)throw new IOException("Um item foi eliminado. Volte a escolher o conteúdo.");String source=row.n("material")>0&&row.containsKey("segment")?"\n\n"+AppLanguage.text(a,"Parte")+" "+(row.n("segment")+1):"";return item.uri.equals("notes")?row.s("body")+(row.s("summary").isEmpty()?"":"\n\n"+row.s("summary"))+source:item.uri.equals("cards")?row.s("front")+"\n\n"+AppLanguage.text(a,"Resposta")+": "+row.s("back")+source:row.s("prompt")+"\n\n"+AppLanguage.text(a,"Resposta")+": "+row.s("answer")+(row.s("explanation").isEmpty()?"":"\n\n"+row.s("explanation"))+source;}
  try(ReaderStore db=new ReaderStore(a);Cursor c=db.getReadableDatabase().query("draft",new String[]{"value","marks"},"uri=? AND segment=? AND digest=?",new String[]{item.uri,""+item.part,item.digest},null,null,null,"1")){if(!c.moveToFirst())throw new IOException("Uma anotação mudou. Volte a escolher os itens.");String value=c.getString(0);JSONArray marks=new JSONArray(c.getString(1));if(item.index>=marks.length())throw new IOException("Uma anotação mudou.");JSONObject mark=marks.getJSONObject(item.index);if(!item.signature.isEmpty()&&!item.signature.equals(ReaderStore.digest(mark.toString())))throw new IOException("Uma anotação mudou. Volte a escolher os itens.");int start=mark.getInt("s"),end=mark.getInt("e");if(start<0||end<start||end>value.length())throw new IOException("Anotação inválida.");String excerpt=value.substring(start,end);return excerpt+(mark.optString("n").isEmpty()?"":"\n\n"+AppLanguage.text(a,"Nota")+": "+mark.optString("n"));}
 }
 File build(List<Choice> chosen)throws Exception{File last=new File(a.getCacheDir(),"seeky-review-"+UUID.randomUUID()+".pdf"),archive=new File(a.getCacheDir(),"seeky-review-"+UUID.randomUUID()+".zip");List<File> volumes=new ArrayList<>();boolean success=false;try{try(PdfWriter pdf=new PdfWriter(title,number->{if(a.getCacheDir().getUsableSpace()<16777216)throw new IOException("Liberte espaço para preparar o caderno.");File file=new File(a.getCacheDir(),"seeky-review-"+UUID.randomUUID()+".pdf");volumes.add(file);return new FileOutputStream(file);})){for(Choice item:chosen){pdf.heading(AppLanguage.text(a,item.kind)+" · "+AudioTitles.limit(item.title,180,512));pdf.source(item.source);pdf.paragraph(body(item));pdf.space();}try(OutputStream out=new FileOutputStream(last)){pdf.write(out);}}if(volumes.isEmpty()){success=true;return last;}volumes.add(last);try(java.util.zip.ZipOutputStream zip=new java.util.zip.ZipOutputStream(new FileOutputStream(archive))){byte[] buffer=new byte[65536];for(int i=0;i<volumes.size();i++){zip.putNextEntry(new java.util.zip.ZipEntry(String.format(Locale.ROOT,"Seeky_Revisao_%03d.pdf",i+1)));try(InputStream in=new FileInputStream(volumes.get(i))){for(int n;(n=in.read(buffer))!=-1;)zip.write(buffer,0,n);}zip.closeEntry();}}for(File file:volumes)file.delete();success=true;return archive;}finally{if(!success){for(File file:volumes)file.delete();last.delete();archive.delete();}}}
 void prepare(List<Choice> chosen){TextView progress=PlusUi.text(a,"A preparar o PDF…",14);UiDialog dialog=new UiDialog.Builder(a).setTitle("Caderno de revisão").setView(progress).setCancelable(false).create();dialog.show();PlusUi.longRun(a,()->{File prepared;try{prepared=build(chosen);}catch(Exception|OutOfMemoryError e){PlusUi.post(a,dialog::dismiss);throw e;}pending=prepared;PlusUi.post(a,()->{dialog.dismiss();try{boolean multiple=prepared.getName().endsWith(".zip");if(multiple)PlusUi.toast(a,"O caderno foi dividido em PDFs de até 150 páginas, dentro de um ZIP.");a.startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType(multiple?"application/zip":"application/pdf").putExtra(Intent.EXTRA_TITLE,multiple?"Seeky_Revisao.zip":"Seeky_Revisao.pdf"),REQUEST);}catch(Exception e){prepared.delete();pending=null;PlusUi.error(a,e);}});});}
 void result(int request,int result,Intent data){if(request!=REQUEST)return;File file=pending;pending=null;if(file==null){if(result==Activity.RESULT_OK)PlusUi.toast(a,"Prepare o caderno novamente.");return;}if(result!=Activity.RESULT_OK||data==null||data.getData()==null){file.delete();return;}Uri target=data.getData();PlusUi.run(a,()->{try(InputStream in=new FileInputStream(file);OutputStream out=a.getContentResolver().openOutputStream(target,"wt")){if(out==null)throw new IOException("Destino indisponível.");byte[] buffer=new byte[65536];for(int n;(n=in.read(buffer))!=-1;)out.write(buffer,0,n);out.flush();PlusUi.post(a,()->PlusUi.toast(a,"Caderno de revisão guardado em PDF."));}finally{file.delete();}});}
 void save(Bundle state){if(pending!=null)state.putString("revision_pdf",pending.getName());}void restore(Bundle state){if(state!=null){String name=state.getString("revision_pdf","");if(name.matches("seeky-review-[a-f0-9-]+\\.(?:pdf|zip)")){File file=new File(a.getCacheDir(),name);if(file.isFile())pending=file;}}}
 static final class PdfWriter implements AutoCloseable {
  PdfDocument doc=new PdfDocument();final Volumes volumes;final int pageLimit;int volume=1;interface Volumes{OutputStream open(int volume)throws IOException;}final Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);final String title;PdfDocument.Page page;Canvas canvas;float y;int pages;long characters;
  PdfWriter(String title){this(title,null,150);}PdfWriter(String title,Volumes volumes){this(title,volumes,150);}PdfWriter(String title,Volumes volumes,int pageLimit){this.title=title;this.volumes=volumes;this.pageLimit=pageLimit;}
  void roll()throws IOException{finish();if(volumes==null)throw new IOException("Escolha menos itens para manter cada caderno abaixo de 150 páginas.");try(OutputStream out=volumes.open(volume++)){doc.writeTo(out);}doc.close();doc=new PdfDocument();pages=0;characters=0;}
  void page()throws IOException{finish();if(pages>=pageLimit)roll();pages++;page=doc.startPage(new PdfDocument.PageInfo.Builder(595,842,pages).create());canvas=page.getCanvas();canvas.drawColor(Color.WHITE);paint.setColor(0xff4d4485);paint.setTextSize(10);paint.setTypeface(Typeface.create("sans-serif",Typeface.BOLD));canvas.drawText(AudioTitles.limit(title,85,256),42,36,paint);paint.setStrokeWidth(1);canvas.drawLine(42,47,553,47,paint);y=75;}
  void finish(){if(page==null)return;paint.setColor(0xff657080);paint.setTypeface(Typeface.create("sans-serif",Typeface.NORMAL));paint.setTextSize(8);canvas.drawText("Seeky · Haidoy Carlos Mautempo",42,816,paint);canvas.drawText(""+pages,535,816,paint);doc.finishPage(page);page=null;}
  void line(String text,float size,boolean bold,int color)throws IOException{if(page==null||y+size+5>786)page();paint.setTextSize(size);paint.setTypeface(Typeface.create("sans-serif",bold?Typeface.BOLD:Typeface.NORMAL));paint.setColor(color);canvas.drawText(text,42,y,paint);y+=size+5;}
  void wrap(String text,float size,boolean bold,int color)throws IOException{if(characters+text.length()>2000000&&volumes!=null&&pages>0)roll();characters+=text.length();if(characters>2000000&&volumes==null)throw new IOException("Escolha menos texto para este caderno.");for(String paragraph:text.replace('\r','\n').split("\n",-1)){if(paragraph.isEmpty()){space();continue;}int at=0;while(at<paragraph.length()){paint.setTextSize(size);paint.setTypeface(Typeface.create("sans-serif",bold?Typeface.BOLD:Typeface.NORMAL));int count=paint.breakText(paragraph,at,paragraph.length(),true,511,null);count=Math.max(1,count);int end=Math.min(paragraph.length(),at+count);if(end<paragraph.length()&&Character.isLowSurrogate(paragraph.charAt(end)))end--;if(end<=at)end=Math.min(paragraph.length(),at+Character.charCount(paragraph.codePointAt(at)));if(end<paragraph.length()){int word=paragraph.lastIndexOf(' ',end);if(word>at+(end-at)/2)end=word;}line(paragraph.substring(at,end),size,bold,color);at=end;while(at<paragraph.length()&&paragraph.charAt(at)==' ')at++;}}}
  void heading(String s)throws IOException{wrap(s,14,true,0xff332d58);}void source(String s)throws IOException{wrap(s,9,false,0xff657080);}void paragraph(String s)throws IOException{wrap(s,12,false,0xff18222c);}void space(){y+=8;}void write(OutputStream out)throws IOException{if(page==null&&pages==0)page();finish();doc.writeTo(out);}public void close(){if(page!=null)doc.finishPage(page);page=null;doc.close();}
 }
}
